#!/data/data/com.termux/files/usr/bin/bash
set -u
REPO="caliofmarian-ai/Practical-Beekeeping-Handbook"

create_issue() {
  local title="$1"
  local body="$2"
  if gh issue list --repo "$REPO" --state all --limit 1000 --json title --jq '.[].title' | grep -Fxq "$title"; then
    echo "SKIP: $title"
  else
    echo "CREATE: $title"
    gh issue create --repo "$REPO" --title "$title" --body "$body" >/dev/null
  fi
}

